#!/bin/bash
# PreToolUse hook (Edit|Write|MultiEdit): block edits to protected paths.
#
# Reads .claude/protected-paths — one glob per line, `# reason — route` after it — and blocks
# (exit 2) any write whose path matches. The message repeats the reason and the route, because a
# block must explain itself (playbook, Stage 5: "when a hook stops an action the reason and the
# route to approval appear in Claude's output"). Generated files (openapi.json, indexes) and
# frozen packages are the typical entries; see the file for the format.
#
# Escape hatch: none inside the session. A protected path changes by changing the generator, or
# by a reviewed edit to .claude/protected-paths itself.
#
# Cheap by design: no jq, no subprocess; the pattern file is read once per invocation (~5 ms).

LIST=".claude/protected-paths"
[[ -f "$LIST" ]] || exit 0

input=$(cat)
[[ "$input" =~ \"file_path\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]] || exit 0
FILE="${BASH_REMATCH[1]}"
ROOT="${CLAUDE_PROJECT_DIR:-$PWD}"
. "${BASH_SOURCE[0]%/*}/lib/winpath.sh"; posix_path FILE; posix_path ROOT   # Windows (local patch)
REL="${FILE#"$ROOT"/}"

# Editing the list itself is allowed (it is reviewed like code).
[[ "$REL" == "$LIST" ]] && exit 0

glob_to_re() {  # glob → anchored ERE
    local g="$1" re="" i c
    for (( i=0; i<${#g}; i++ )); do
        c="${g:$i:1}"
        case "$c" in
            '*') if [[ "${g:$i:3}" == "**/" ]]; then re+="(.*/)?"; i=$((i+2));
                 elif [[ "${g:$i:2}" == "**" ]]; then re+=".*"; i=$((i+1));
                 else re+="[^/]*"; fi ;;
            '?') re+="." ;;
            '.'|'+'|'('|')'|'$'|'^'|'{'|'}'|'|'|'\\') re+="\\$c" ;;
            *) re+="$c" ;;
        esac
    done
    printf '^%s$' "$re"
}

while IFS= read -r line || [[ -n "$line" ]]; do
    pattern="${line%%#*}"; pattern="${pattern%"${pattern##*[![:space:]]}"}"; pattern="${pattern#"${pattern%%[![:space:]]*}"}"
    [[ -z "$pattern" ]] && continue
    reason="${line#*#}"; [[ "$reason" == "$line" ]] && reason="protected path"
    reason="${reason#"${reason%%[![:space:]]*}"}"
    re=$(glob_to_re "$pattern")
    if [[ "$REL" =~ $re ]]; then
        cat >&2 <<MSG
⛔ Protected path: \`$REL\`

  rule:   $pattern   (.claude/protected-paths)
  reason: $reason

Do not edit this file directly. Follow the route in the reason above; if the rule itself is
wrong, change .claude/protected-paths in a reviewed commit and say why.
MSG
        TOOL=""; [[ "$input" =~ \"tool_name\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]] && TOOL="${BASH_REMATCH[1]}"
        mkdir -p .claude/session-state 2>/dev/null && printf '{"ts":%s,"tool":"%s","duration_ms":null,"decision":"blocked","hook":"%s","target":"%s"}\n' \
          "$(date +%s)000" "$TOOL" "protected-paths-gate" "$REL" >> .claude/session-state/tool-log.jsonl 2>/dev/null
        exit 2
    fi
done < "$LIST"
exit 0
